import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, float, mix, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-1-label';

  const {
    position = [-3.2, 1, 0.06],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
  } = config.scenePlacement || {};

  group.position.set(...position);
  group.rotation.set(...rotation);
  group.scale.set(...scale);

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const inkColor = new THREE.Color('#16161d');
  const paperColor = new THREE.Color('#e8ecf2');
  const accentColor = new THREE.Color('#ff2a38');
  const surfaceColor = new THREE.Color('#0b0b10');

  const material = new THREE.MeshBasicNodeMaterial();

  let colorNode;
  let map = null;

  const imageUrl = '/prism-mock/home/nodes/orb-decor.png';
  if (imageUrl && ctx.textureLoader) {
    map = ctx.textureLoader.load(imageUrl);
    map.colorSpace = THREE.SRGBColorSpace;

    const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
    const atlasSize = { w: 512, h: 320 };

    const uOffset = atlasRect.x / atlasSize.w;
    const vOffset = 1.0 - (atlasRect.y + atlasRect.h) / atlasSize.h;
    const uScale = atlasRect.w / atlasSize.w;
    const vScale = atlasRect.h / atlasSize.h;

    const remappedUv = uv().mul(vec3(uScale, vScale, 1.0).xy).add(vec3(uOffset, vOffset, 0.0).xy);
    const texSample = texture(map, remappedUv);

    // Engineered gradient overlay: surface -> ink diagonal blend
    const gradientMix = uv().x.add(uv().y).mul(0.5);
    const gradient = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), gradientMix);

    colorNode = mix(vec4(gradient, 1.0), texSample, texSample.a);
  } else {
    const gradientMix = uv().x.add(uv().y).mul(0.5);
    const gradient = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), gradientMix);
    colorNode = vec4(gradient, 1.0);
  }

  material.colorNode = colorNode;
  material.transparent = false;

  const planeMesh = new THREE.Mesh(geometry, material);
  planeMesh.name = 'pricing-card-1-label-plane';
  group.add(planeMesh);

  // Headline text: "Pricing 1"
  let textMesh = null;
  if (ctx.fontAtlas) {
    textMesh = createTextMesh({
      text: 'Pricing 1',
      font: 'Lora',
      weight: 400,
      role: 'headline',
      sizeEm: 0.34,
      color: paperColor,
      atlas: ctx.fontAtlas,
      align: 'center',
      anchor: 'center',
    });
    textMesh.position.set(0, 0, 0.01);
    textMesh.name = 'pricing-card-1-label-text';
    group.add(textMesh);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
